from collections.abc import Iterable, Mapping, Sequence

def total(prices: Iterable[float]) -> float:
    return sum(prices)

def first_last(items: Sequence[str]) -> tuple[str, str]:
    return items[0], items[-1]

def lookup(table: Mapping[str, int], key: str) -> int:
    return table.get(key, 0)

print(total([1.5, 2.5]), total(p for p in (1.0, 2.0)))   # 4.0 3.0
print(first_last(("a", "b", "c")))                       # ('a', 'c')
print(lookup({"x": 1}, "y"))                             # 0

scores: dict[str, list[int]] = {}
scores.setdefault("ada", []).append(95)
point: tuple[int, int] = (3, 4)
coords: tuple[float, ...] = (1.0, 2.0, 3.0)
print(scores, point, coords)

def parse_port(raw: str | None) -> int:
    if raw is None:                 # narrowed: raw is str below
        return 8080
    return int(raw)

def describe(value: int | str | list[int]) -> str:
    if isinstance(value, int):
        return f"int {value + 1}"   # value: int
    elif isinstance(value, str):
        return value.upper()        # value: str
    return f"{len(value)} items"    # value: list[int]

print(parse_port(None), parse_port("9000"))   # 8080 9000
print(describe(41), describe("hi"), describe([1, 2]))
# int 42 HI 2 items

def bad(name: str | None) -> int:
    return len(name)                # checker error: "str | None" passed to len()

from collections.abc import Callable

def apply_twice(fn: Callable[[int], int], x: int) -> int:
    return fn(fn(x))

def notify(handler: Callable[[str], object], msg: str) -> None:
    handler(msg)                         # result ignored, so return type object

def make_multiplier(k: int) -> Callable[[int], int]:
    return lambda n: n * k

print(apply_twice(lambda n: n + 3, 1))   # 7
print(apply_twice(make_multiplier(10), 2))   # 200
notify(print, "saved")                   # saved
notify(len, "ok")                        # fine: len returns int, object accepts it
# apply_twice(str.upper, 1)  -> checker error: incompatible Callable type

from typing import Protocol, runtime_checkable

@runtime_checkable
class Shape(Protocol):
    name: str
    def area(self) -> float: ...

class Square:                       # no inheritance from Shape
    name = "square"
    def __init__(self, side: float) -> None:
        self.side = side
    def area(self) -> float:
        return self.side ** 2

class Label:
    name = "label"

def report(shapes: list[Shape]) -> list[str]:
    return [f"{s.name}: {s.area():.1f}" for s in shapes]

print(report([Square(2)]))                         # ['square: 4.0']
print(isinstance(Square(1), Shape), isinstance(Label(), Shape))  # True False
# report([Label()])  -> checker error: "Label" is missing "area"

from collections.abc import Sequence

def first[T](items: Sequence[T]) -> T:
    return items[0]

def longest[S: (str, bytes)](a: S, b: S) -> S:   # constrained: str or bytes
    return a if len(a) >= len(b) else b

class Stack[T]:
    def __init__(self) -> None:
        self._items: list[T] = []
    def push(self, item: T) -> None:
        self._items.append(item)
    def pop(self) -> T:
        return self._items.pop()

n = first([10, 20])            # checker: int
s = Stack[str]()
s.push("a")
print(n + 1, s.pop().upper(), longest("ab", "c"))   # 11 A ab
print(Stack.__type_params__)   # (T,)
# s.push(3)          -> checker error: expected "str"
# longest("a", b"b") -> checker error: mixed str and bytes

from enum import Enum
from typing import TypeGuard, TypeIs, assert_never

class Status(Enum):
    ACTIVE, BANNED = 1, 2

def is_str(x: object) -> TypeIs[str]:
    return isinstance(x, str)

def is_str_list(val: list[object]) -> TypeGuard[list[str]]:   # list is invariant,
    return all(isinstance(x, str) for x in val)               # so TypeIs can't be used

def label(s: Status) -> str:
    match s:
        case Status.ACTIVE: return "ok"
        case Status.BANNED: return "blocked"
        case _:
            assert_never(s)        # checker error here if a member is unhandled

def show(x: int | str) -> str:
    return x.upper() if is_str(x) else str(x + 1)   # else branch: x is int

items: list[object] = ["a", "b"]
if is_str_list(items): print(", ".join(items))   # a, b  (items: list[str])
print(show("hi"), show(1), label(Status.BANNED))   # HI 2 blocked

import functools
from collections.abc import Callable
from typing import Concatenate, Self

def logged[**P, R](fn: Callable[P, R]) -> Callable[P, R]:
    @functools.wraps(fn)
    def wrapper(*args: P.args, **kwargs: P.kwargs) -> R:
        print(f"calling {fn.__name__}{args}")
        return fn(*args, **kwargs)
    return wrapper

def with_retries[**P, R](fn: Callable[Concatenate[int, P], R]) -> Callable[P, R]:
    def wrapper(*args: P.args, **kwargs: P.kwargs) -> R:
        return fn(3, *args, **kwargs)        # injects the first argument
    return wrapper

@logged
def add(a: int, b: int) -> int: return a + b
@with_retries
def download(retries: int, url: str) -> str: return f"{url} x{retries}"
class Query:
    def where(self, cond: str) -> Self: print("where", cond); return self
print(add(2, 3), download("a.io"))    # calling add(2, 3) / 5 a.io x3
Query().where("x > 1").where("y < 2")  # where x > 1 / where y < 2
# add("2", 3) -> checker error, because the signature was preserved

from collections.abc import Callable, Sequence

def mean(xs: Sequence[float]) -> float:      # covariant: list[int] is accepted
    return sum(xs) / len(xs)

def add_half(xs: list[float]) -> None:       # invariant: needs exactly list[float]
    xs.append(0.5)

class Reader[T]:                             # T only returned -> inferred covariant
    def __init__(self, value: T) -> None:
        self._value = value
    def get(self) -> T:
        return self._value

def read_number(r: Reader[float]) -> float:
    return r.get()

ints: list[int] = [1, 2, 3]
print(mean(ints), read_number(Reader(4)))   # 2.0 4
handler: Callable[[int], object] = lambda x: float(x)   # contravariant parameter
# add_half(ints) -> checker error: list[int] is not list[float] (list is invariant)
